    q, r = divmod(abs_num, denominator)

    if mode == "half_up":
        if r * 2 > denominator:
            q += 1
        elif r * 2 == denominator:
            q += 1
        return q * sign

    if mode == "half_even":
        if r * 2 > denominator:
            q += 1
        elif r * 2 == denominator:
            if q % 2 != 0:
                q += 1
        return q * sign

    raise ValueError(f"Unknown mode: {mode}
